class Solution { public int minNumberOfFrogs(String croak){String order="croak";int[] stage=new int[5];int active=0,answer=0;for(char value:croak.toCharArray()){int index=order.indexOf(value);if(index<0)return -1;if(index==0){stage[0]++;active++;answer=Math.max(answer,active);}else{if(stage[index-1]==0)return -1;stage[index-1]--;if(index==4)active--;else stage[index]++;}}for(int i=0;i<4;i++)if(stage[i]!=0)return -1;return active==0?answer:-1;} }
